#ifdef ALEX_GHC
data AlexAddr = AlexA# Addr#
-- Do not remove this comment. Required to fix CPP parsing when using GCC and a clang-compiled alex.

{-# INLINE alexIndexInt16OffAddr #-}
alexIndexInt16OffAddr :: AlexAddr -> Int# -> Int#
alexIndexInt16OffAddr (AlexA# arr) off =
#ifdef WORDS_BIGENDIAN
  narrow16Int# i
  where
        i    = word2Int# ((high `uncheckedShiftL#` 8#) `or#` low)
        high = int2Word# (ord# (indexCharOffAddr# arr (off' +# 1#)))
        low  = int2Word# (ord# (indexCharOffAddr# arr off'))
        off' = off *# 2#
#else
#if __GLASGOW_HASKELL__ >= 901
  GHC.Exts.int16ToInt#
#endif
    (indexInt16OffAddr# arr off)
#endif
#else
alexIndexInt16OffAddr = (Data.Array.!)
#endif

#ifdef ALEX_GHC
{-# INLINE alexIndexInt32OffAddr #-}
alexIndexInt32OffAddr :: AlexAddr -> Int# -> Int#
alexIndexInt32OffAddr (AlexA# arr) off =
#ifdef WORDS_BIGENDIAN
  narrow32Int# i
  where
   i    = word2Int# ((b3 `uncheckedShiftL#` 24#) `or#`
                     (b2 `uncheckedShiftL#` 16#) `or#`
                     (b1 `uncheckedShiftL#` 8#) `or#` b0)
   b3   = int2Word# (ord# (indexCharOffAddr# arr (off' +# 3#)))
   b2   = int2Word# (ord# (indexCharOffAddr# arr (off' +# 2#)))
   b1   = int2Word# (ord# (indexCharOffAddr# arr (off' +# 1#)))
   b0   = int2Word# (ord# (indexCharOffAddr# arr off'))
   off' = off *# 4#
#else
#if __GLASGOW_HASKELL__ >= 901
  GHC.Exts.int32ToInt#
#endif
    (indexInt32OffAddr# arr off)
#endif
#else
alexIndexInt32OffAddr = (Data.Array.!)
#endif

#ifdef ALEX_GHC
-- GHC >= 503, unsafeAt is available from Data.Array.Base.
quickIndex = unsafeAt
#else
quickIndex = (Data.Array.!)
#endif

-- -----------------------------------------------------------------------------
-- Main lexing routines

data AlexReturn a
  = AlexEOF
  | AlexError  !AlexInput
  | AlexSkip   !AlexInput !Int
  | AlexToken  !AlexInput !Int a

-- alexScan :: AlexInput -> StartCode -> AlexReturn a
alexScan input__ IBOX(sc)
  = alexScanUser undefined input__ IBOX(sc)

alexScanUser user__ input__ IBOX(sc)
  = case alex_scan_tkn user__ input__ ILIT(0) input__ sc AlexNone of
  (AlexNone, input__') ->
    case alexGetByte input__ of
      Nothing ->
#ifdef ALEX_DEBUG
                                   Debug.Trace.trace ("End of input.") $
#endif
                                   AlexEOF
      Just _ ->
#ifdef ALEX_DEBUG
                                   Debug.Trace.trace ("Error.") $
#endif
                                   AlexError input__'

  (AlexLastSkip input__'' len, _) ->
#ifdef ALEX_DEBUG
    Debug.Trace.trace ("Skipping.") $
#endif
    AlexSkip input__'' len

  (AlexLastAcc k input__''' len, _) ->
#ifdef ALEX_DEBUG
    Debug.Trace.trace ("Accept.") $
#endif
    AlexToken input__''' len ((Data.Array.!) alex_actions k)


-- Push the input through the DFA, remembering the most recent accepting
-- state it encountered.

alex_scan_tkn user__ orig_input len input__ s last_acc =
  input__ `seq` -- strict in the input
  let
  new_acc = (check_accs (alex_accept `quickIndex` IBOX(s)))
  in
  new_acc `seq`
  case alexGetByte input__ of
     Nothing -> (new_acc, input__)
     Just (c, new_input) ->
#ifdef ALEX_DEBUG
      Debug.Trace.trace ("State: " ++ show IBOX(s) ++ ", char: " ++ show c ++ " " ++ (show . chr . fromIntegral) c) $
#endif
      case fromIntegral c of { IBOX(ord_c) ->
        let
                base   = alexIndexInt32OffAddr alex_base s
                offset = PLUS(base,ord_c)

                new_s = if GTE(offset,ILIT(0))
                          && let check  = alexIndexInt16OffAddr alex_check offset
                             in  EQ(check,ord_c)
                          then alexIndexInt16OffAddr alex_table offset
                          else alexIndexInt16OffAddr alex_deflt s
        in
        case new_s of
            ILIT(-1) -> (new_acc, input__)
                -- on an error, we want to keep the input *before* the
                -- character that failed, not after.
            _ -> alex_scan_tkn user__ orig_input
#ifdef ALEX_LATIN1
                   PLUS(len,ILIT(1))
                   -- issue 119: in the latin1 encoding, *each* byte is one character
#else
                   (if c < 0x80 || c >= 0xC0 then PLUS(len,ILIT(1)) else len)
                   -- note that the length is increased ONLY if this is the 1st byte in a char encoding)
#endif
                   new_input new_s new_acc
      }
  where
        check_accs (AlexAccNone) = last_acc
        check_accs (AlexAcc a  ) = AlexLastAcc a input__ IBOX(len)
        check_accs (AlexAccSkip) = AlexLastSkip  input__ IBOX(len)
#ifndef ALEX_NOPRED
        check_accs (AlexAccPred a predx rest)
           | predx user__ orig_input IBOX(len) input__
           = AlexLastAcc a input__ IBOX(len)
           | otherwise
           = check_accs rest
        check_accs (AlexAccSkipPred predx rest)
           | predx user__ orig_input IBOX(len) input__
           = AlexLastSkip input__ IBOX(len)
           | otherwise
           = check_accs rest
#endif

data AlexLastAcc
  = AlexNone
  | AlexLastAcc !Int !AlexInput !Int
  | AlexLastSkip     !AlexInput !Int

data AlexAcc user
  = AlexAccNone
  | AlexAcc Int
  | AlexAccSkip
#ifndef ALEX_NOPRED
  | AlexAccPred Int (AlexAccPred user) (AlexAcc user)
  | AlexAccSkipPred (AlexAccPred user) (AlexAcc user)

type AlexAccPred user = user -> AlexInput -> Int -> AlexInput -> Bool

-- -----------------------------------------------------------------------------
-- Predicates on a rule

alexAndPred p1 p2 user__ in1 len in2
  = p1 user__ in1 len in2 && p2 user__ in1 len in2

--alexPrevCharIsPred :: Char -> AlexAccPred _
alexPrevCharIs c _ input__ _ _ = c == alexInputPrevChar input__

alexPrevCharMatches f _ input__ _ _ = f (alexInputPrevChar input__)

--alexPrevCharIsOneOfPred :: Array Char Bool -> AlexAccPred _
alexPrevCharIsOneOf arr _ input__ _ _ = arr Data.Array.! alexInputPrevChar input__

--alexRightContext :: Int -> AlexAccPred _
alexRightContext IBOX(sc) user__ _ _ input__ =
     case alex_scan_tkn user__ input__ ILIT(0) input__ sc AlexNone of
          (AlexNone, _) -> False
          _ -> True
        -- TODO: there's no need to find the longest
        -- match when checking the right context, just
        -- the first match will do.
#endif
{-# LINE 402 "src/Language/JavaScript/Parser/Lexer.x" #-}
{-
-- The next function select between the two lex input states, as called for in
-- secion 7 of ECMAScript Language Specification, Edition 3, 24 March 2000.

The method is inspired by the lexer in http://jint.codeplex.com/
-}

classifyToken :: Token -> Int
classifyToken aToken =
    case aToken of
        IdentifierToken {}   -> divide
        NullToken {}         -> divide
        TrueToken {}         -> divide
        FalseToken {}        -> divide
        ThisToken {}         -> divide
        OctalToken {}        -> divide
        DecimalToken {}      -> divide
        HexIntegerToken {}   -> divide
        StringToken {}       -> divide
        RightCurlyToken {}   -> divide
        RightParenToken {}   -> divide
        RightBracketToken {} -> divide
        _other               -> reg


lexToken :: Alex Token
lexToken = do
    inp <- alexGetInput
    lt  <- getLastToken
    case lt of
        TailToken {} -> alexEOF
        _other -> do
            isInTmpl <- getInTemplate
            let state = if isInTmpl then template else classifyToken lt
            setInTemplate False -- the inTemplate condition only needs to last for one token
            case alexScan inp state of
                AlexEOF        -> do
                    tok <- tailToken
                    setLastToken tok
                    return tok
                AlexError (pos,_,_,_) ->
                    alexError ("lexical error @ line " ++ show (getLineNum(pos)) ++
                                                " and column " ++ show (getColumnNum(pos)))
                AlexSkip inp' _len -> do
                    alexSetInput inp'
                    lexToken
                AlexToken inp' len action -> do
                    alexSetInput inp'
                    tok <- action inp len
                    setLastToken tok
                    return tok

-- For tesing.
alexTestTokeniser :: String -> Either String [Token]
alexTestTokeniser input =
    runAlex input $ loop []
  where
    loop acc = do
        tok <- lexToken
        case tok of
            EOFToken {} ->
                return $ case acc of
                            [] -> []
                            (TailToken{}:xs) -> reverse xs
                            xs -> reverse xs
            _ -> loop (tok:acc)

-- For testing with ASI (Automatic Semicolon Insertion) support
-- This version includes comment tokens in the output for testing
alexTestTokeniserASI :: String -> Either String [Token]
alexTestTokeniserASI input =
    runAlex input $ loop []
  where
    loop acc = do
        tok <- lexToken
        case tok of
            EOFToken {} ->
                return $ case acc of
                            [] -> []
                            (TailToken{}:xs) -> reverse xs
                            xs -> reverse xs
            CommentToken {} -> do
                if shouldTriggerASI acc
                    then maybeAutoSemiTest tok acc
                    else loop (tok:acc)
            WsToken {} -> do
                if shouldTriggerASI acc
                    then maybeAutoSemiTest tok acc  
                    else loop (tok:acc)
            _ -> do
                setLastToken tok
                loop (tok:acc)
    
    -- Test version that includes tokens in output stream
    maybeAutoSemiTest (WsToken sp tl cmt) acc =
        if hasNewlineTest tl
            then loop (AutoSemiToken sp tl cmt : WsToken sp tl cmt : acc)
            else loop (WsToken sp tl cmt : acc)
    maybeAutoSemiTest (CommentToken sp tl cmt) acc =
        if hasNewlineTest tl  
            then loop (AutoSemiToken sp tl cmt : CommentToken sp tl cmt : acc)
            else loop (CommentToken sp tl cmt : acc)
    maybeAutoSemiTest tok acc = loop (tok:acc)
    
    -- Check for newlines including all JavaScript line terminators
    hasNewlineTest :: ByteString -> Bool
    hasNewlineTest bs = BS8.any (`elem` ['\n', '\r']) bs || 
                        BS8.isInfixOf u2028 bs || BS8.isInfixOf u2029 bs
      where
        u2028 = BS8.pack "\226\128\168"  -- UTF-8 encoding of U+2028 (Line Separator)
        u2029 = BS8.pack "\226\128\169"  -- UTF-8 encoding of U+2029 (Paragraph Separator)
    
    -- Check if we should trigger ASI by looking for recent return/break/continue tokens
    shouldTriggerASI :: [Token] -> Bool
    shouldTriggerASI = any isASITrigger . take 5  -- Look at last 5 tokens
      where
        isASITrigger (ReturnToken {}) = True
        isASITrigger (BreakToken {}) = True  
        isASITrigger (ContinueToken {}) = True
        isASITrigger _ = False

-- This is called by the Happy parser.
lexCont :: (Token -> Alex a) -> Alex a
lexCont cont =
    lexLoop
  where
    lexLoop = do
        tok <- lexToken
        case tok of
            CommentToken {} -> do
                addComment tok
                ltok <- getLastToken
                case ltok of
                    BreakToken {} -> maybeAutoSemi tok
                    ContinueToken {} -> maybeAutoSemi tok
                    ReturnToken {} -> maybeAutoSemi tok
                    _otherwise -> lexLoop
            WsToken {} -> do
                addComment tok
                ltok <- getLastToken
                case ltok of
                    BreakToken {} -> maybeAutoSemi tok
                    ContinueToken {} -> maybeAutoSemi tok
                    ReturnToken {} -> maybeAutoSemi tok
                    _otherwise -> lexLoop
            _other -> do
                cs <- getComment
                let tok' = tok{ tokenComment=(toCommentAnnotation cs) }
                setComment []
                cont tok'

    -- If the token contains a newline, convert it to an AutoSemiToken and call 
    -- the continuation, otherwise, just lexLoop. Now handles both WsToken and CommentToken.
    maybeAutoSemi (WsToken sp tl cmt) =
        if hasNewline tl
            then cont $ AutoSemiToken sp tl cmt
            else lexLoop
    maybeAutoSemi (CommentToken sp tl cmt) =
        if hasNewline tl
            then cont $ AutoSemiToken sp tl cmt
            else lexLoop
    maybeAutoSemi _ = lexLoop

    -- Check for newlines including all JavaScript line terminators
    hasNewline :: ByteString -> Bool
    hasNewline bs = BS8.any (`elem` ['\n', '\r']) bs || 
                    BS8.isInfixOf u2028 bs || BS8.isInfixOf u2029 bs
      where
        u2028 = BS8.pack "\226\128\168"  -- UTF-8 encoding of U+2028 (Line Separator)
        u2029 = BS8.pack "\226\128\169"  -- UTF-8 encoding of U+2029 (Paragraph Separator)


toCommentAnnotation :: [Token] -> [CommentAnnotation]
toCommentAnnotation [] = []
toCommentAnnotation xs =
    reverse $ map go xs
  where
    go tok@(CommentToken {}) = (CommentA (tokenSpan tok) (tokenLiteral tok))
    go tok@(WsToken      {}) = (WhiteSpace (tokenSpan tok) (tokenLiteral tok))
    go _                     = error "toCommentAnnotation"

-- ---------------------------------------------------------------------

getLineNum :: AlexPosn -> Int
getLineNum (AlexPn _offset lineNum _colNum) = lineNum

getColumnNum :: AlexPosn -> Int
getColumnNum (AlexPn _offset _lineNum colNum) = colNum

-- ---------------------------------------------------------------------

getLastToken :: Alex Token
getLastToken = Alex $ \s@AlexState{alex_ust=ust} -> Right (s, previousToken ust)

setLastToken :: Token -> Alex ()
setLastToken (WsToken {}) = Alex $ \s -> Right (s, ())
setLastToken tok          = Alex $ \s -> Right (s{alex_ust=(alex_ust s){previousToken=tok}}, ())

getComment :: Alex [Token]
getComment = Alex $ \s@AlexState{alex_ust=ust} -> Right (s, comment ust)


addComment :: Token -> Alex ()
addComment c = Alex $ \s ->  Right (s{alex_ust=(alex_ust s){comment=c:(  comment (alex_ust s)  )}}, ())


setComment :: [Token] -> Alex ()
setComment cs = Alex $ \s -> Right (s{alex_ust=(alex_ust s){comment=cs }}, ())

getInTemplate :: Alex Bool
getInTemplate = Alex $ \s@AlexState{alex_ust=ust} -> Right (s, inTemplate ust)

setInTemplate :: Bool -> Alex ()
setInTemplate it = Alex $ \s -> Right (s{alex_ust=(alex_ust s){inTemplate=it}}, ())

alexEOF :: Alex Token
alexEOF = return (EOFToken tokenPosnEmpty [])

tailToken :: Alex Token
tailToken = return (TailToken tokenPosnEmpty [])

adapt :: (TokenPosn -> Int -> String -> Alex Token) -> AlexInput -> Int -> Alex Token
adapt f ((AlexPn offset line col),_,_,inp) len = f (TokenPn offset line col) len inp

toTokenPosn :: AlexPosn -> TokenPosn
toTokenPosn (AlexPn offset line col) = (TokenPn offset line col)

-- ---------------------------------------------------------------------

-- a keyword or an identifier (the syntax overlaps)
keywordOrIdent :: String -> TokenPosn -> Alex Token
keywordOrIdent str location =
    return $ case Map.lookup str keywords of
                Just symbol -> symbol location (stringToUtf8ByteString str) []
                Nothing -> IdentifierToken location (stringToUtf8ByteString str) []
  where
    -- Helper function for proper UTF-8 encoding of Haskell String to ByteString
    stringToUtf8ByteString :: String -> ByteString
    stringToUtf8ByteString = Text.encodeUtf8 . Text.pack

-- mapping from strings to keywords
keywords :: Map.Map String (TokenPosn -> ByteString -> [CommentAnnotation] -> Token)
keywords = Map.fromList keywordNames

keywordNames :: [(String, TokenPosn -> ByteString -> [CommentAnnotation] -> Token)]
keywordNames =
    [ ( "async", AsyncToken )
    , ( "await", AwaitToken )
    , ( "break", BreakToken )
    , ( "case", CaseToken )
    , ( "catch", CatchToken )

    , ( "class", ClassToken )
    , ( "const", ConstToken ) -- not a keyword, nominally a future reserved word, but actually in use

    , ( "continue", ContinueToken )
    , ( "debugger", DebuggerToken )
    , ( "default", DefaultToken )
    , ( "delete", DeleteToken )
    , ( "do", DoToken )
    , ( "else", ElseToken )

    , ( "enum", EnumToken )  -- not a keyword,  nominally a future reserved word, but actually in use
    , ( "export", ExportToken )
    , ( "extends", ExtendsToken )

    , ( "false", FalseToken ) -- boolean literal

    , ( "finally", FinallyToken )
    , ( "for", ForToken )
    , ( "function", FunctionToken )
    , ( "from", FromToken )
    , ( "if", IfToken )
    , ( "import", ImportToken )
    , ( "in", InToken )
    , ( "instanceof", InstanceofToken )
    , ( "let", LetToken )
    , ( "new", NewToken )

    , ( "null", NullToken ) -- null literal

    , ( "of", OfToken )
    , ( "return", ReturnToken )
    , ( "static", StaticToken )
    , ( "super", SuperToken )
    , ( "switch", SwitchToken )
    , ( "this", ThisToken )
    , ( "throw", ThrowToken )
    , ( "true", TrueToken )
    , ( "try", TryToken )
    , ( "typeof", TypeofToken )
    , ( "var", VarToken )
    , ( "void", VoidToken )
    , ( "while", WhileToken )
    , ( "with", WithToken )
    , ( "yield", YieldToken )
    -- TODO: no idea if these are reserved or not, but they are needed
    --       handled in parser, in the Identifier rule
    , ( "as", AsToken ) -- not reserved
    , ( "get", GetToken )
    , ( "set", SetToken )
    {- Come from Table 6 of ECMASCRIPT 5.1, Attributes of a Named Accessor Property
       Also include

         Enumerable
